// Generated by the actual ClawHub producer from an inert, full-ledger child.
func completeBundleFixture(t *testing.T) (json.RawMessage, map[string]any) {
	t.Helper()
	raw, err := os.ReadFile("testdata/skillspector-bundled-complete-caveat.json")
	if err != nil {
		t.Fatal(err)
	}
	var report map[string]any
	if err := json.Unmarshal(raw, &report); err != nil {
		t.Fatal(err)
	}
	return raw, report
}

func TestClawHubCompleteCaveatBundleReachesJudgeWithoutLosingOriginals(t *testing.T) {
	raw, _ := completeBundleFixture(t)
	for _, exitCode := range []int{0, 1} {
		result := validateSkillSpectorReportForProfile(ScannerResult{Status: "completed", ExitCode: intPointer(exitCode), Raw: raw}, "clawhub")
		if result.Status != "completed" || result.ReportPolicy != "" || !bytes.Equal(result.Raw, raw) {
			t.Fatalf("complete child evidence lost: %+v", result)
		}
		prompt, err := RenderClawHubPrompt("Independently inspect original evidence.", Artifact{Profile: "clawhub", Scanners: map[string]ScannerResult{"skillspector": result}})
		for _, evidence := range []string{"complete_with_caveats", "skills/council-network/SKILL.md", "runtime-note.md", "reference_missing", "RA2", "llm-unconfirmed", "disagreed", "0.99"} {
			if err != nil || !strings.Contains(prompt, evidence) {
				t.Fatalf("judge lost %s: err=%v", evidence, err)
			}
		}
	}
}

func TestClawHubCompleteCaveatBundleRequiresConfiguredAnalyzerReceipts(t *testing.T) {
	for _, mode := range []string{"missing", "integrity-only", "unknown"} {
		t.Run(mode, func(t *testing.T) {
			_, report := completeBundleFixture(t)
			child := report["bundled_reports"].([]any)[0].(map[string]any)["report"].(map[string]any)
			accounting := child["analysis_completeness"].(map[string]any)
			kept := []any{}
			for _, value := range accounting["analyzer_statuses"].([]any) {
				row := value.(map[string]any)
				id := row["analyzer_id"].(string)
				if mode == "missing" && id == "semantic_security_discovery" || mode == "integrity-only" && id != "artifact_integrity" {
					continue
				}
				if mode == "unknown" && id == "semantic_security_discovery" {
					row["analyzer_id"] = "unregistered_scanner"
				}
				kept = append(kept, row)
			}
			accounting["analyzer_statuses"] = kept
			raw, err := json.Marshal(report)
			if err != nil {
				t.Fatal(err)
			}
			result := validateSkillSpectorReportForProfile(ScannerResult{Status: "completed", Raw: raw}, "clawhub")
			if result.Status != "failed" {
				t.Fatalf("missing or unknown configured analyzer receipts admitted: %s", result.Status)
			}
		})
	}
}

