func TestClawHubCompleteCaveatBundlePreservesAccountedScopes(t *testing.T) {
	for _, mode := range []string{"archive", "image", "wave", "archive-image"} {
		t.Run(mode, func(t *testing.T) {
			_, report := completeBundleFixture(t)
			child := caveatScopeFixture(t, strings.Contains(mode, "archive"), strings.Contains(mode, "image"))
			if mode == "wave" {
				child, _, _ = waveScopeFixture(t)
			}
			accounting := child["analysis_completeness"].(map[string]any)
			accounting["status"], accounting["is_complete"] = "complete_with_caveats", true
			report["bundled_reports"].([]any)[0].(map[string]any)["report"] = child
			raw, _ := json.Marshal(report)
			result := validateSkillSpectorReportForProfile(ScannerResult{Status: "completed", Raw: raw}, "clawhub")
			if result.Status != "completed" || !bytes.Equal(result.Raw, raw) {
				t.Fatalf("honest %s scope rejected or raw changed: %+v", mode, result)
			}
		})
	}
}

func TestClawHubCompleteCaveatBundleDerivesJudgeRiskFromOriginalChildren(t *testing.T) {
	for _, mode := range []string{"wrapper", "child-alias", "finding-cap", "second-child"} {
		t.Run(mode, func(t *testing.T) {
			_, report := completeBundleFixture(t)
			entry := report["bundled_reports"].([]any)[0].(map[string]any)
			child := entry["report"].(map[string]any)
			high := child["issues"].([]any)[0].(map[string]any)
			high["id"], high["severity"] = "RAW-HIGH", "HIGH"
			child["risk_assessment"] = map[string]any{"score": float64(90), "severity": "HIGH", "recommendation": "REVIEW"}
			count, root := 1, "skills/council-network"
			if mode == "child-alias" {
				child["filtered_findings"], child["issue_count"], child["risk_score"], child["status"] = []any{}, float64(0), float64(0), "clean"
			}
			if mode == "finding-cap" {
				issues := []any{}
				for i := range 25 {
					issues = append(issues, map[string]any{"id": fmt.Sprintf("LOW-%d", i), "severity": "LOW", "file": "SKILL.md"})
				}
				child["issues"] = append(issues, high)
				count = 26
				accounting := child["analysis_completeness"].(map[string]any)
				accounting["findings_before_filtering"], accounting["findings_after_filtering"] = float64(count), float64(count)
			}
			if mode == "second-child" {
				_, other := completeBundleFixture(t)
				otherEntry := other["bundled_reports"].([]any)[0].(map[string]any)
				entry["rootPath"] = "skills/second"
				report["bundled_reports"] = []any{otherEntry, entry}
				count, root = 2, "skills/second"
			}
			report["status"], report["issue_count"], report["filtered_findings"] = "clean", float64(0), []any{}
			report["risk_assessment"] = map[string]any{"score": float64(0), "severity": "NONE", "recommendation": "SAFE"}
			raw, _ := json.Marshal(report)
			result := validateSkillSpectorReportForProfile(ScannerResult{Status: "completed", Raw: raw}, "clawhub")
			if result.Status != "completed" || !bytes.Equal(result.Raw, raw) {
				t.Fatalf("valid original children rejected or changed: %s", result.Status)
			}
			normalized, err := normalizeClawHubSkillSpector(raw, 123)
			if err != nil || normalized.Status != "suspicious" || normalized.Score == nil || *normalized.Score != 90 || normalized.Severity != "HIGH" || normalized.IssueCount != count || len(normalized.Issues) != min(count, 25) || normalized.Issues[0].IssueID != "RAW-HIGH" || normalized.Issues[0].File != root+"/SKILL.md" {
				t.Fatalf("child risk hidden by display aggregate: %+v err=%v", normalized, err)
			}
			prompt, err := RenderClawHubPrompt("Independently inspect original evidence.", Artifact{Profile: "clawhub", Scanners: map[string]ScannerResult{"skillspector": result}})
			for _, evidence := range []string{"RAW-HIGH", "HIGH", root + "/SKILL.md", "llm-unconfirmed", "disagreed", "0.99"} {
				if err != nil || !strings.Contains(prompt, evidence) {
					t.Fatalf("actual judge prompt lost %s: %v", evidence, err)
				}
			}
		})
	}
}

func TestClawHubCompleteCaveatBundleDoesNotInventFindingsOrClearMaliciousStatus(t *testing.T) {
	for _, expected := range []string{"clean", "malicious"} {
		t.Run(expected, func(t *testing.T) {
			_, report := completeBundleFixture(t)
			child := report["bundled_reports"].([]any)[0].(map[string]any)["report"].(map[string]any)
			child["issues"], child["status"] = []any{}, expected
			accounting := child["analysis_completeness"].(map[string]any)
			accounting["findings_before_filtering"], accounting["findings_after_filtering"] = float64(0), float64(0)
			risk := map[string]any{"score": float64(0), "severity": "NONE", "recommendation": "SAFE"}
			child["risk_assessment"], report["risk_assessment"] = risk, risk
			report["status"], report["issue_count"], report["filtered_findings"] = "clean", float64(0), []any{}
			raw, _ := json.Marshal(report)
			normalized, err := normalizeClawHubSkillSpector(raw, 123)
			if err != nil || normalized.Status != expected || normalized.IssueCount != 0 || len(normalized.Issues) != 0 {
				t.Fatalf("child status lost or finding invented: %+v err=%v", normalized, err)
			}
		})
	}
}

func TestClawHubCompleteCaveatBundleRejectsUnattestedOrContradictoryChildren(t *testing.T) {
	tests := []struct {
		name, section, key string
		value              any
	}{
		{"wrapper-failed", "wrapper", "execution_successful", false},
		{"wrapper-alias", "wrapper", "Execution_Successful", true},
		{"wrapper-unknown", "wrapper", "unknown", true},
		{"wrapper-partial", "wrapperAccounting", "is_complete", false},
		{"wrapper-count", "wrapperAccounting", "total_components", 1},
		{"zero-children", "wrapper", "bundled_reports", []any{}},
		{"empty-root", "entry", "rootPath", ""}, {"absolute-root", "entry", "rootPath", "/escape"},
		{"drive-root", "entry", "rootPath", "C:/escape"},
		{"traversal-root", "entry", "rootPath", "skills/../escape"}, {"backslash-root", "entry", "rootPath", `skills\escape`},
		{"child-failed", "child", "execution_successful", false}, {"child-missing-execution", "child", "execution_successful", nil},
		{"child-nonboolean-execution", "child", "execution_successful", "true"},
		{"child-error", "child", "error", "crashed"}, {"child-alias", "child", "isComplete", true},
		{"nested-bundle", "child", "bundled_reports", []any{}},
		{"missing-complete", "accounting", "is_complete", nil}, {"false-complete", "accounting", "is_complete", false},
		{"nonboolean-complete", "accounting", "is_complete", "true"},
		{"missing-nested-execution", "accounting", "execution_successful", nil},
		{"missing-ledger", "accounting", "ledger_exceptions", nil}, {"empty-ledger", "accounting", "ledger_exceptions", []any{}},
		{"missing-refs", "accounting", "references", nil}, {"empty-refs", "accounting", "references", []any{}},
		{"missing-analyzers", "accounting", "analyzer_statuses", nil}, {"empty-analyzers", "accounting", "analyzer_statuses", []any{}},
		{"partial-count", "accounting", "partially_inspected_files", 1}, {"uninspected-count", "accounting", "entirely_uninspected_files", 1},
		{"dishonest-total", "accounting", "total_components", 100}, {"string-count", "accounting", "scanned_components", "2"},
		{"oversized-count", "accounting", "findings_before_filtering", float64(1 << 32)},
		{"missing-count", "accounting", "fully_inspected_files", nil}, {"missing-limitations", "accounting", "limitations", nil},
		{"real-limitation", "accounting", "limitations", []any{"static_parse_limit"}},
		{"unknown-accounting", "accounting", "unknown", true}, {"accounting-alias", "accounting", "Is_Complete", true},
		{"fatal", "exception", "fatal", true}, {"fatal-alias", "exception", "Fatal", true},
		{"wrong-reason", "exception", "reason_code", "reference_unresolved"}, {"unmatched-path", "exception", "path", "other.md"},
		{"unmatched-ref", "reference", "line", 1}, {"uninspected-ref", "reference", "status", "uninspected"},
		{"unknown-ref", "reference", "unknown", true}, {"bad-disposition", "reference", "disposition", "analyzed"},
		{"oversized-column", "reference", "column", float64(1 << 32)}, {"null-evidence", "reference", "evidence", json.RawMessage(`null`)},
		{"degraded-analyzer", "analyzer", "status", "degraded"}, {"unaccounted-analyzer", "analyzer", "unaccounted", 1},
		{"missing-analyzer-count", "analyzer", "completed", nil}, {"analyzer-alias", "analyzer", "Completed", 2},
	}
	for _, test := range tests {
		t.Run(test.name, func(t *testing.T) {
			_, report := completeBundleFixture(t)
			entry := report["bundled_reports"].([]any)[0].(map[string]any)
			child := entry["report"].(map[string]any)
			accounting := child["analysis_completeness"].(map[string]any)
			sections := map[string]map[string]any{"wrapper": report, "wrapperAccounting": report["analysis_completeness"].(map[string]any), "entry": entry, "child": child, "accounting": accounting,
				"exception": accounting["ledger_exceptions"].([]any)[0].(map[string]any), "reference": accounting["references"].([]any)[0].(map[string]any), "analyzer": accounting["analyzer_statuses"].([]any)[0].(map[string]any)}
			if test.value == nil {
				delete(sections[test.section], test.key)
			} else {
				sections[test.section][test.key] = test.value
			}
			raw, err := json.Marshal(report)
			if err != nil {
				t.Fatal(err)
			}
			result := validateSkillSpectorReportForProfile(ScannerResult{Status: "completed", Raw: raw}, "clawhub")
			if result.Status != "failed" {
				t.Fatalf("unattested complete bundle admitted: %+v", result)
			}
		})
	}
}

func TestClawHubCompleteCaveatBundleRequiresActualCaveatAndDisjointRoots(t *testing.T) {
	for _, mode := range []string{"ordinary-only", "nested-root", "duplicate-analyzer"} {
		t.Run(mode, func(t *testing.T) {
			_, report := completeBundleFixture(t)
			entries := report["bundled_reports"].([]any)
			child := entries[0].(map[string]any)["report"].(map[string]any)
			accounting := child["analysis_completeness"].(map[string]any)
			switch mode {
			case "ordinary-only":
				accounting["status"], accounting["ledger_exceptions"], accounting["references"] = "complete", []any{}, []any{}
			case "nested-root":
				report["bundled_reports"] = append(entries, map[string]any{"rootPath": "skills/council-network/nested", "report": child})
			case "duplicate-analyzer":
				rows := accounting["analyzer_statuses"].([]any)
				accounting["analyzer_statuses"] = append(rows, rows[0])
			}
			raw, _ := json.Marshal(report)
			if result := validateSkillSpectorReportForProfile(ScannerResult{Status: "completed", Raw: raw}, "clawhub"); result.Status != "failed" {
				t.Fatalf("invalid complete wrapper admitted: %+v", result)
			}
		})
	}
}

