func TestClawHubCompleteCaveatBundleBoundsSummariesWithoutLosingRawChildren(t *testing.T) {
	_, report := completeBundleFixture(t)
	entries := []any{}
	for index := range 12 {
		_, childReport := completeBundleFixture(t)
		entry := childReport["bundled_reports"].([]any)[0].(map[string]any)
		entry["rootPath"] = fmt.Sprintf("skills/child-%d", index)
		accounting := entry["report"].(map[string]any)["analysis_completeness"].(map[string]any)
		accounting["references"].([]any)[0].(map[string]any)["evidence"] = strings.Repeat("x", 3000)
		accounting["ledger_exceptions"].([]any)[0].(map[string]any)["message"] = strings.Repeat("y", 3000)
		entries = append(entries, entry)
	}
	report["bundled_reports"] = entries
	raw, _ := json.Marshal(report)
	result := validateSkillSpectorReportForProfile(ScannerResult{Status: "completed", Raw: raw}, "clawhub")
	if result.Status != "completed" || !bytes.Equal(result.Raw, raw) {
		t.Fatalf("full original child evidence lost: %+v", result)
	}
	normalized, err := normalizeClawHubSkillSpector(raw, 123)
	if err != nil {
		t.Fatal(err)
	}
	caveats := normalized.InspectionCaveats
	if caveats == nil || caveats.ReferenceCount != 12 || caveats.ExceptionCount != 12 || len(caveats.References) != 10 || len(caveats.LedgerExceptions) != 10 {
		t.Fatalf("bounded summaries lost full counts: %+v", caveats)
	}
	if caveats.References[0]["sourcePath"] != "skills/child-0/SKILL.md" || caveats.References[0]["evidence"] != strings.Repeat("x", 512)+"\n...[truncated 2488 chars]" || caveats.LedgerExceptions[0]["message"] != strings.Repeat("y", 512)+"\n...[truncated 2488 chars]" {
		t.Fatalf("rooted summary exceeded bounds: %+v", caveats)
	}
	if normalized.Issues[0].IssueID != "RA2" || normalized.Issues[0].Severity != "MEDIUM" || *normalized.Issues[0].Confidence != 0.7 || normalized.Issues[0].ReviewOutcome != "disagreed" || *normalized.Issues[0].ReviewConfidence != 0.99 {
		t.Fatalf("summary truncation changed retained finding: %+v", normalized)
	}
}

func TestClawHubCompleteCaveatBundleRejectsDuplicateRootsAndUnattestedOrdinaryChild(t *testing.T) {
	for _, ordinary := range []bool{false, true} {
		_, report := completeBundleFixture(t)
		entries := report["bundled_reports"].([]any)
		if ordinary {
			entries = append(entries, map[string]any{"rootPath": "skills/unattested", "report": map[string]any{"execution_successful": true, "issues": []any{}, "analysis_completeness": map[string]any{"execution_successful": true, "is_complete": true, "status": "complete"}}})
		} else {
			entries = append(entries, entries[0])
		}
		report["bundled_reports"] = entries
		raw, _ := json.Marshal(report)
		if result := validateSkillSpectorReportForProfile(ScannerResult{Status: "completed", Raw: raw}, "clawhub"); result.Status != "failed" {
			t.Fatalf("invalid child mixture admitted: %+v", result)
		}
	}
}

func TestClawHubCompleteCaveatBundleStillAppliesFindingGate(t *testing.T) {
	for _, mode := range []string{"honest-summary", "forged-clean-summary", "display-only-high", "high-after-presentation-cap"} {
		t.Run(mode, func(t *testing.T) {
			_, report := completeBundleFixture(t)
			child := report["bundled_reports"].([]any)[0].(map[string]any)["report"].(map[string]any)
			child["issues"].([]any)[0].(map[string]any)["severity"] = "HIGH"
			report["filtered_findings"].([]any)[0].(map[string]any)["severity"] = "HIGH"
			if mode == "display-only-high" {
				child["issues"].([]any)[0].(map[string]any)["severity"] = "MEDIUM"
			}
			if mode == "high-after-presentation-cap" {
				issues := []any{}
				for index := range 25 {
					issues = append(issues, map[string]any{"id": fmt.Sprintf("CRITICAL-%d", index), "severity": "CRITICAL", "file": "SKILL.md"})
				}
				child["issues"] = append(issues, child["issues"].([]any)[0])
				accounting := child["analysis_completeness"].(map[string]any)
				accounting["findings_before_filtering"], accounting["findings_after_filtering"] = float64(26), float64(26)
			}
			if mode == "forged-clean-summary" || mode == "high-after-presentation-cap" {
				report["status"], report["issue_count"], report["filtered_findings"] = "clean", float64(0), []any{}
				report["risk_assessment"] = map[string]any{"score": float64(0), "severity": "NONE", "recommendation": "SAFE"}
			}
			raw, err := json.Marshal(report)
			if err != nil {
				t.Fatal(err)
			}
			target := t.TempDir()
			for name, content := range map[string]string{"openclaw.plugin.json": `{"id":"generated-bundle"}`, "skills/council-network/SKILL.md": "# Generated inert fixture\n", "skills/council-network/fixture-001.md": "Generated companion.\n"} {
				path := filepath.Join(target, filepath.FromSlash(name))
				if err := os.MkdirAll(filepath.Dir(path), 0o700); err != nil {
					t.Fatal(err)
				}
				if err := os.WriteFile(path, []byte(content), 0o600); err != nil {
					t.Fatal(err)
				}
			}
			path := filepath.Join(t.TempDir(), "report.json")
			if err := os.WriteFile(path, raw, 0o600); err != nil {
				t.Fatal(err)
			}
			command := judgeRetryCommand(func(workspace string, _ time.Duration) (CommandOutput, error) {
				return judgeRetryOutput(t, map[string]any{"verdict": "benign", "artifact_inspection": partialJudgeReceipt(t, workspace)}), nil
			})
			artifact, err := Run(Options{Profile: "clawhub", Target: target, Scanners: []string{"skillspector"}, ScannerResultPaths: map[string]string{"skillspector": path}, Judge: &JudgeOptions{Command: "judge"}, GateRules: map[string]ScannerGatePolicy{"skillspector": {JSONRules: []JSONGateRule{{ID: "retained-bundle-high", Paths: []string{"filtered_findings[].severity"}, Equals: json.RawMessage(`"HIGH"`), Action: "block"}}}}}, RunContext{Env: map[string]string{}, CommandRunner: command})
			if err != nil || !artifact.Complete || artifact.Gate != "block" || len(artifact.GateRules) != 1 || !bytes.Equal(artifact.Scanners["skillspector"].Raw, raw) {
				t.Fatalf("complete wrapper bypassed finding gate: gate=%s rules=%+v err=%v", artifact.Gate, artifact.GateRules, err)
			}
		})
	}
}
